export const ORBIT_PRIMITIVE_KEYS = [
  'storage_put',
  'storage_get',
  'storage_list',
  'storage_delete',
  'storage_url',
  'cache_get',
  'cache_set',
  'cache_delete',
  'socket_url',
  'socket_broadcast',
  'socket_stats',
  'tools_search',
  'tools_describe',
  'tools_namespaces',
  'db_exec',
  'db_query',
  'db_first',
  'db_batch',
  'ai_run',
  'ai_generate',
  'ai_summarize',
  'ai_embed',
  'ai_classify',
  'ai_rerank',
  'ai_models',
] as const
export type OrbitPrimitiveKey = (typeof ORBIT_PRIMITIVE_KEYS)[number]

export const WFP_NATIVE_PRIMITIVE_KEYS = [
  'db_exec',
  'db_query',
  'db_first',
  'db_batch',
] as const satisfies readonly OrbitPrimitiveKey[]

type WfpNativePrimitiveKey = (typeof WFP_NATIVE_PRIMITIVE_KEYS)[number]

export const HOST_CALL_PRIMITIVE_KEYS = ORBIT_PRIMITIVE_KEYS.filter(
  (key): key is Exclude<OrbitPrimitiveKey, WfpNativePrimitiveKey> =>
    !(WFP_NATIVE_PRIMITIVE_KEYS as readonly string[]).includes(key)
)

export function orbitAppListRow(app: OrbitAppSummary) {
  return {
    name: app.name,
    status: app.status,
    latest_version: app.latest_version ?? null,
    url: app.url,
    access: app.access,
  }
}

export function orbitAppDetailView(app: OrbitAppDetail) {
  return {
    name: app.name,
    status: app.status,
    latest_version: app.latest_version,
    url: app.url,
    access: app.access,
    routes: app.routes.length,
    jobs: Object.keys(app.jobs).length,
    versions: app.versions.length,
  }
}

export function orbitJobListRow(job: OrbitJobSummary) {
  return {
    name: job.name,
    status: job.status,
    latest_version: job.latest_version ?? null,
    capabilities: job.capabilities,
    kind: job.kind ?? null,
    tags: job.tags ?? [],
  }
}

export function orbitJobDetailView(job: OrbitJobDetail) {
  return {
    name: job.name,
    status: job.status,
    latest_version: job.latest_version,
    capabilities: job.capabilities,
    versions: job.versions.length,
    kind: job.kind ?? null,
    tags: job.tags ?? [],
    has_input_schema: job.input_schema !== null,
    has_output_schema: job.output_schema !== null,
  }
}

export function orbitJobVersionRow(version: OrbitJobVersionRecord) {
  return {
    version: version.version,
    status: version.status,
    lane: version.lane,
    capabilities: version.capabilities,
    created_at: version.created_at,
    error: version.error_message,
  }
}
