export const TriggerIdempotencyPolicy = Schema.Struct({
  key: Schema.Array(Schema.NonEmptyString),
  ttl_seconds: Schema.optional(Schema.Number),
})
export type TriggerIdempotencyPolicy = typeof TriggerIdempotencyPolicy.Type

export const TriggerConcurrencyPolicy = Schema.Struct({
  scope: Schema.optional(TriggerConcurrencyScope),
  key: Schema.Array(Schema.NonEmptyString),
  limit: Schema.Number,
  overflow: TriggerConcurrencyOverflow,
  ttl_seconds: Schema.optional(Schema.Number),
})
export type TriggerConcurrencyPolicy = typeof TriggerConcurrencyPolicy.Type

export const TriggerRetryPolicy = Schema.Struct({
  max_attempts: Schema.optional(Schema.Number),
  backoff: Schema.optional(Schema.Literals(['none', 'fixed', 'exponential'])),
})
export type TriggerRetryPolicy = typeof TriggerRetryPolicy.Type

export const TriggerRetentionPolicy = Schema.Struct({
  event_ttl_seconds: Schema.optional(Schema.Number),
  delivery_ttl_seconds: Schema.optional(Schema.Number),
})
export type TriggerRetentionPolicy = typeof TriggerRetentionPolicy.Type

// Workspace trigger limit floors are part of the contract: every numeric
// field must be a positive integer, and `max_event_bytes` must be at least
// 1 KiB (smaller webhook bodies are not actionable). There is intentionally
// no upper bound here — the server is authoritative for the operational
// ceiling, and the UI should not invent caps that the contract does not
// guarantee. Floors are enforced at decode time on inbound requests and
// at encode time on outbound responses via the route's response schema.
const TriggerLimitCount = Schema.Number.check(Schema.isInt(), Schema.isGreaterThanOrEqualTo(1))
const TriggerLimitEventBytes = Schema.Number.check(
  Schema.isInt(),
  Schema.isGreaterThanOrEqualTo(1024)
)

export const TriggerLimits = Schema.Struct({
  max_active_triggers: Schema.optional(TriggerLimitCount),
  max_active_schedules: Schema.optional(TriggerLimitCount),
  max_due_per_tick: Schema.optional(TriggerLimitCount),
  max_concurrent_deliveries: Schema.optional(TriggerLimitCount),
  max_concurrent_cron_deliveries: Schema.optional(TriggerLimitCount),
  max_concurrent_webhook_deliveries: Schema.optional(TriggerLimitCount),
  min_cron_interval_seconds: Schema.optional(TriggerLimitCount),
  max_event_bytes: Schema.optional(TriggerLimitEventBytes),
})
export type TriggerLimits = typeof TriggerLimits.Type

